q=A.w(j,A.bHq(q,B.aa,3,!1,B.aa,B.zo,j,A.a([A.oo(B.ajH,k.hI(e,"Wer ist Kkaebi?","Who is Kkaebi?","\u0915\u0948\u092c\u0940 \u0915\u094c\u0928 \u0939\u0948?","\u30c8\u30c3\u30b1\u30d3\u3068\u306f\uff1f","\uae68\ube44\ub294 \ub204\uad6c?","\u5409\u9b3c\u662f\u8c01\uff1f")),A.oo(B.ahO,k.hI(e,"DOK-KEY Anleitung","App Guide",h,"DOK-KEY \u8aac\u660e\u66f8","DOK-KEY \ub3c4\uc6c0\ub9d0","\u7cfb\u7edf\u8bf4\u660e\u4e66"))],s),B.uO),B.j,B.m8,j,j,j,j,j,j,j,j,j,j)
